SELECT ?ahu ?zone ?z_name WHERE {
  ?ahu a brick:AirHandlingUnit ; rdfs:label "AHU02" .
  ?ahu brick:feeds ?zone .
  ?zone rdfs:label ?z_name .
}

SELECT ?ahu ?zone WHERE {
  ?ahu a brick:AirHandlingUnit .
  FILTER(str(?ahu)="AHU02" || str(?ahu) LIKE "%AHU02%")
  ?ahu brick:feeds ?zone .
}

SELECT ?ahu ?zone ?zrel WHERE {
  ?ahu a brick:AirHandlingUnit .
  ?ahu ?zrel ?zone .
  FILTER(str(?zrel) LIKE "brick:%")
}

